package bitmapkernel

import (
	"testing"

	"github.com/evanoberholster/imageIdx/internal/bench"
)

// Deterministic scalar-versus-dispatch matrix. Both implementations run on
// the exact same word slices, generated by the shared bench harness, so the
// comparison isolates the active SIMD backend from the scalar reference:
//
//	go test ./roar/internal/bitmapkernel/ -run='^$' -bench='BenchmarkKernel' -benchmem -count=10
//
// Sub-benchmarks are named BenchmarkKernel/<Scalar|Dispatch>/<Op>/Density=<tier>.

// matrixSink consumes kernel results so the compiler cannot eliminate them.
var matrixSink uint64

// matrixWords builds one 1,024-word (65,536-bit) container from the shared
// harness. Keeping only BitmapIDs' first container yields exactly the density
// tier's per-container cardinality: 256 bits for Sparse, 32,768 for Dense.
func matrixWords(seed int64, d bench.Density) []uint64 {
	words := make([]uint64, testWords)
	for _, id := range bench.BitmapIDs(seed, 1<<16, d) {
		if id>>16 != 1 {
			continue
		}
		low := uint16(id)
		words[low>>6] |= uint64(1) << (low & 63)
	}
	return words
}

type matrixBinaryOp struct {
	name     string
	scalar   func(dst, a, b []uint64) uint32
	dispatch func(dst, a, b []uint64) uint32
}

type matrixCountOp struct {
	name     string
	scalar   func(words []uint64) uint64
	dispatch func(words []uint64) uint64
}

type matrixPredicateOp struct {
	name     string
	scalar   func(a, b []uint64) bool
	dispatch func(a, b []uint64) bool
}

// BenchmarkKernel compares the scalar reference kernels with the dispatched
// entry points on identical sparse and dense word slices.
func BenchmarkKernel(b *testing.B) {
	binaries := []matrixBinaryOp{
		{name: "And", scalar: andScalar, dispatch: And},
		{name: "Or", scalar: orScalar, dispatch: Or},
		{name: "AndNot", scalar: andNotScalar, dispatch: AndNot},
	}
	counters := []matrixCountOp{
		{name: "Cardinality", scalar: cardinalityScalar, dispatch: Cardinality},
	}
	predicates := []matrixPredicateOp{
		{name: "Intersects", scalar: intersectsScalar, dispatch: Intersects},
	}

	densities := []bench.Density{bench.Sparse, bench.Dense}
	for densityIndex, density := range densities {
		wordsA := matrixWords(int64(100+densityIndex), density)
		wordsB := matrixWords(int64(200+densityIndex), density)
		dst := make([]uint64, testWords)
		densityLabel := "Density=" + density.String()

		for _, implementation := range []string{"Scalar", "Dispatch"} {
			for _, op := range binaries {
				fn := op.dispatch
				if implementation == "Scalar" {
					fn = op.scalar
				}
				b.Run(implementation+"/"+op.name+"/"+densityLabel, func(b *testing.B) {
					b.ReportAllocs()
					b.ResetTimer()
					for b.Loop() {
						matrixSink = uint64(fn(dst, wordsA, wordsB))
					}
				})
			}
			for _, op := range counters {
				fn := op.dispatch
				if implementation == "Scalar" {
					fn = op.scalar
				}
				b.Run(implementation+"/"+op.name+"/"+densityLabel, func(b *testing.B) {
					b.ReportAllocs()
					b.ResetTimer()
					for b.Loop() {
						matrixSink = fn(wordsA)
					}
				})
			}
			for _, op := range predicates {
				fn := op.dispatch
				if implementation == "Scalar" {
					fn = op.scalar
				}
				b.Run(implementation+"/"+op.name+"/"+densityLabel, func(b *testing.B) {
					b.ReportAllocs()
					b.ResetTimer()
					for b.Loop() {
						if fn(wordsA, wordsB) {
							matrixSink = 1
						} else {
							matrixSink = 0
						}
					}
				})
			}
		}
	}
}
